cat > evp_bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <openssl/crypto.h>

int main() {
    printf("OpenSSL %s\n", OpenSSL_version(OPENSSL_VERSION));
    printf("ia32cap: %s\n", getenv("OPENSSL_ia32cap") ? getenv("OPENSSL_ia32cap") : "(default)");
    size_t n = 20ull * 1024 * 1024;
    unsigned char *data = malloc(n);
    memset(data, 0x5a, n);
    unsigned char out[32];

    // warmup
    SHA256(data, n, out);

    int reps = 3;
    clock_t t0 = clock();
    for (int r = 0; r < reps; r++) SHA256(data, n, out);
    clock_t t1 = clock();

    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    for (int r = 0; r < reps; r++) {
        EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
        EVP_DigestUpdate(ctx, data, n);
        unsigned int len = 32;
        EVP_DigestFinal_ex(ctx, out, &len);
    }
    clock_t t2 = clock();
    printf("SHA256() %.4f\n", (double)(t1-t0)/CLOCKS_PER_SEC/reps);
    printf("EVP      %.4f\n", (double)(t2-t1)/CLOCKS_PER_SEC/reps);

    // multi-stream: hash 4 independent buffers interleaved? not helpful for single hash.
    // Try hashing with smaller updates to see overhead
    t0 = clock();
    for (int r = 0; r < reps; r++) {
        SHA256_CTX c;
        SHA256_Init(&c);
        size_t off = 0;
        size_t chunk = 1024*1024;
        while (off < n) {
            size_t m = n - off; if (m > chunk) m = chunk;
            SHA256_Update(&c, data+off, m);
            off += m;
        }
        SHA256_Final(out, &c);
    }
    t1 = clock();
    printf("chunked  %.4f\n", (double)(t1-t0)/CLOCKS_PER_SEC/reps);
    return 0;
}
