};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32-n)); }
static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

/* Process 4 sequential blocks. state is the starting state; result is after 4 blocks.
   This is sequential dependency so we CANNOT do 4 independent states of one chain.
   Instead this function hashes 4 INDEPENDENT messages (same length, 1 block each) — for speed test of round function. */
static void sha256_4x1block(uint32_t st[4][8], const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3) {
    uint32_t w0[64], w1[64], w2[64], w3[64];
    const uint8_t *ms[4] = {m0,m1,m2,m3};
    uint32_t *ws[4] = {w0,w1,w2,w3};
    for (int k = 0; k < 4; k++) {
        const uint32_t *src = (const uint32_t*)ms[k];
        for (int i = 0; i < 16; i++) ws[k][i] = bswap32(src[i]);
        for (int i = 16; i < 64; i++) {
            uint32_t s0 = rotr(ws[k][i-15],7) ^ rotr(ws[k][i-15],18) ^ (ws[k][i-15]>>3);
            uint32_t s1 = rotr(ws[k][i-2],17) ^ rotr(ws[k][i-2],19) ^ (ws[k][i-2]>>10);
            ws[k][i] = ws[k][i-16] + s0 + ws[k][i-7] + s1;
        }
    }
    __m128i a = _mm_setr_epi32(st[0][0], st[1][0], st[2][0], st[3][0]);
    __m128i b = _mm_setr_epi32(st[0][1], st[1][1], st[2][1], st[3][1]);
    __m128i c = _mm_setr_epi32(st[0][2], st[1][2], st[2][2], st[3][2]);
    __m128i d = _mm_setr_epi32(st[0][3], st[1][3], st[2][3], st[3][3]);
    __m128i e = _mm_setr_epi32(st[0][4], st[1][4], st[2][4], st[3][4]);
    __m128i f = _mm_setr_epi32(st[0][5], st[1][5], st[2][5], st[3][5]);
    __m128i g = _mm_setr_epi32(st[0][6], st[1][6], st[2][6], st[3][6]);
    __m128i h = _mm_setr_epi32(st[0][7], st[1][7], st[2][7], st[3][7]);
    __m128i sa=a,sb=b,sc=c,sd=d,se=e,sf=f,sg=g,sh=h;

    for (int i = 0; i < 64; i++) {
        __m128i ki = _mm_set1_epi32(K[i]);
        __m128i wi = _mm_setr_epi32(w0[i], w1[i], w2[i], w3[i]);
        // S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25)
        __m128i S1 = _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(e,6), _mm_ror_epi32(e,11)), _mm_ror_epi32(e,25));
        // ch = (e & f) ^ (~e & g)
        __m128i ch = _mm_xor_si128(_mm_and_si128(e, f), _mm_andnot_si128(e, g));
        __m128i t1 = _mm_add_epi32(h, _mm_add_epi32(S1, _mm_add_epi32(ch, _mm_add_epi32(ki, wi))));
        __m128i S0 = _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(a,2), _mm_ror_epi32(a,13)), _mm_ror_epi32(a,22));
        __m128i maj = _mm_xor_si128(_mm_xor_si128(_mm_and_si128(a,b), _mm_and_si128(a,c)), _mm_and_si128(b,c));
        __m128i t2 = _mm_add_epi32(S0, maj);
        h = g; g = f; f = e; e = _mm_add_epi32(d, t1);
