static inline __m256i ROR(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}
static inline __m256i s0(__m256i x) { return _mm256_xor_si256(ROR(x,7), _mm256_xor_si256(ROR(x,18), _mm256_srli_epi32(x,3))); }
static inline __m256i s1(__m256i x) { return _mm256_xor_si256(ROR(x,17), _mm256_xor_si256(ROR(x,19), _mm256_srli_epi32(x,10))); }

/* Load 16 big-endian words from 8 messages into 16 ymm regs (each lane = one message). */
static inline __m256i load_be(const uint8_t *p0, const uint8_t *p1, const uint8_t *p2, const uint8_t *p3,
                              const uint8_t *p4, const uint8_t *p5, const uint8_t *p6, const uint8_t *p7, int word) {
    uint32_t v[8];
    const uint8_t *ps[8] = {p0,p1,p2,p3,p4,p5,p6,p7};
    for (int i = 0; i < 8; i++) {
        const uint8_t *q = ps[i] + word*4;
        v[i] = ((uint32_t)q[0]<<24)|((uint32_t)q[1]<<16)|((uint32_t)q[2]<<8)|q[3];
    }
    return _mm256_loadu_si256((const __m256i*)v);
}

static void sha256_8way(uint32_t state[8][8],
                        const uint8_t *b0, const uint8_t *b1, const uint8_t *b2, const uint8_t *b3,
                        const uint8_t *b4, const uint8_t *b5, const uint8_t *b6, const uint8_t *b7) {
