    __m256i c_ = _mm256_loadu_si256((__m256i*)C0);
    __m256i d_ = _mm256_loadu_si256((__m256i*)D0);
    __m256i e_ = _mm256_loadu_si256((__m256i*)E0);
    __m256i f_ = _mm256_loadu_si256((__m256i*)F0);
    __m256i g_ = _mm256_loadu_si256((__m256i*)G0);
    __m256i h_ = _mm256_loadu_si256((__m256i*)H0);
