    for (int i = 0; i < 64; i++) {
        __m256i S1 = _mm256_xor_si256(ROR(e_,6), _mm256_xor_si256(ROR(e_,11), ROR(e_,25)));
        __m256i ch = _mm256_xor_si256(_mm256_and_si256(e_, f_), _mm256_andnot_si256(e_, g_));
        __m256i t1 = _mm256_add_epi32(h_, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(Kc[i]), W[i]))));
        __m256i S0 = _mm256_xor_si256(ROR(a_,2), _mm256_xor_si256(ROR(a_,13), ROR(a_,22)));
        __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(a_, b_), _mm256_and_si256(a_, c_)), _mm256_and_si256(b_, c_));
