    _mm256_storeu_si256((__m256i*)E0,e_); _mm256_storeu_si256((__m256i*)F0,f_);
    _mm256_storeu_si256((__m256i*)G0,g_); _mm256_storeu_si256((__m256i*)H0,h_);
